beforeSaveCustomScript:
if (bySystem && entity\isAttributeChanged('bySystem')) {
    description = 'Problema asociado con el equipo no tiene nada que ver con un ataque real';
}

if (urgent && entity\isAttributeChanged('urgent')) {
    record\create(
        'Task',
        'name', string\concatenate('Revisión urgente de incidente: ', name),
        'description', 'Incidente marcado como urgente. Revisar inmediatamente.',
        'status', 'Not Started',
        'parentType', 'CIncident',
        'parentId', id,
        'assignedUserId', assignedUserId
    );
}

if (
    !entity\isNew()
    && entity\isAttributeChanged('actionsTaken')
    && array\includes(actionsTaken, 'Sospecha de falso positivo')
) {
    record\create(
        'Task',
        'name', 'TASK FALSO POSITIVO TEST',
        'description', 'Prueba de falso positivo.',
        'status', 'Not Started',
        'parentType', 'CIncident',
        'parentId', id,
        'assignedUserId', assignedUserId
    );
}
if (createCase && entity\isAttributeChanged('createCase')) {
    record\create(
        'Case',
        'name', string\concatenate('Caso generado por incidente: ', name),
        'description', description,
        'status', 'New',
        'assignedUserId', assignedUserId
    );
}

if (string\pos(description, 'urgente') != false) {
    status = 'Urgente';
}



entity\clearAttribute('name');
